    "サーバーからインストールと認証の情報が届くのを待っています。",
  "Cursor is turned off on this machine, so account model discovery is not running. Enable it and complete setup to check available models.":
    "このマシンでは Cursor がオフのため、アカウントのモデル検出は行われていません。有効にしてセットアップを完了すると、利用可能なモデルを確認できます。",
  "{reach}: favorites, visibility and order. These preferences follow the provider instance ID, including matching default slots on other machines.":
    "{reach}：お気に入り、表示、並び順。これらの設定はプロバイダーのインスタンス ID に従い、ほかのマシンの対応する既定スロットにも適用されます。",
  "{name} cleared because the server address changed. Enter it again to use it there.":
    "サーバーのアドレスが変わったため、{name} をクリアしました。そこで使うにはもう一度入力してください。",
  "Uses Cursor’s Agent SDK with a local agent loop and hosted inference. Sign in with your Cursor account or use an API key. SDK access may require a paid Cursor plan; models and usage depend on your account.":
    "Cursor の Agent SDK を使い、エージェントループはローカルで、推論はホスト側で実行します。Cursor アカウントでサインインするか、API キーを使ってください。SDK の利用には Cursor の有料プランが必要な場合があります。モデルと使用量はアカウントによって異なります。",
  "Cursor API key": "Cursor API キー",
