  "Add an API account": "API アカウントを追加",
  "Turns on this account are billed per token to its credits at API prices, not to your subscription. Create the key in the {console}. Add one account per key; when one runs out of credits, a stopped thread can continue on the next.":
    "このアカウントでのターンは、サブスクリプションではなく、そのクレジットから API 料金でトークン単位に課金されます。キーは {console} で作成してください。キーごとに 1 つのアカウントを追加します。あるアカウントのクレジットが尽きたら、停止したスレッドは次のアカウントで続行できます。",
  "API key": "API キー",
  "Workspace ID (optional)": "ワークスペース ID（任意）",
  "A workspace ID starts with wrkspc_.": "ワークスペース ID は wrkspc_ で始まります。",
  "Needed for a key that is not scoped to a workspace (user keys, sk-ant-usr…). Copy it from Settings → Workspaces in the Claude Console.":
    "ワークスペースに限定されていないキー（ユーザーキー、sk-ant-usr…）では必要です。Claude Console の Settings → Workspaces からコピーしてください。",
