  "app-wide reviewer order": "アプリ全体のレビュアーの順序",
  "Uses the {button}; customize to give this project its own.":
    "{button}を使用中です。カスタマイズすると、このプロジェクト独自の順序にできます。",
  "App-wide for this machine; a project can set its own in its settings.":
    "このマシンのアプリ全体に適用されます。プロジェクトは自身の設定で独自に指定できます。",
  "fallback order": "フォールバック順序",
  "response style": "応答スタイル",
  "Changes what coordinators, workers and threads write, for every provider. The reply button in a thread or project header sets it for that project. Timeline detail only changes how much of their work is shown. New turns use the saved style.":
    "すべてのプロバイダーで、コーディネーター、ワーカー、スレッドが書く内容を変えます。スレッドやプロジェクトのヘッダーにある返信ボタンで、そのプロジェクト用に設定できます。タイムラインの詳細度は、作業をどれだけ表示するかだけを変えます。新しいターンは保存したスタイルを使います。",
  "Applies to Claude Code providers with native workflow support. Workers already running keep their launch settings.":
    "ネイティブのワークフローに対応した Claude Code プロバイダーに適用されます。実行中のワーカーは起動時の設定を保ちます。",
  "agent instructions": "エージェントへの指示",
  "Mixed. Enter instructions to apply to all selected targets.":
    "混在しています。選択したすべての対象に適用する指示を入力してください。",
  "Add project conventions, goals, and verification rules.":
    "プロジェクトの規約、目標、検証ルールを追加します。",
  "Add your working preferences and shared rules.": "作業の好みと共通のルールを追加します。",
  "SpecWithCode adds its own rules (response style, safety and orchestration) after these; editing or clearing this text never removes them. Native project instructions remain included. These reach every coordinator and worker on Claude Code, Codex, Cursor, OpenCode and ACP agents, and Claude workflow workers. New sessions and resumed turns use the saved rules; running workers keep their launch context.":
    "SpecWithCode はこれらの後に独自のルール（応答スタイル、安全性、オーケストレーション）を追加します。このテキストを編集・消去しても、それらは削除されません。ネイティブのプロジェクト指示も引き続き含まれます。これらは Claude Code、Codex、Cursor、OpenCode、ACP エージェントのすべてのコーディネーターとワーカー、そして Claude のワークフロー ワーカーに届きます。新しいセッションと再開したターンは保存したルールを使い、実行中のワーカーは起動時のコンテキストを保ちます。",
  "Effective instructions preview": "有効な指示のプレビュー",
  "Global instructions": "グローバルな指示",
  "Global instructions + project additions": "グローバルな指示 + プロジェクトの追加分",
  "Connect a selected environment to edit agent instructions.":
    "エージェントへの指示を編集するには、選択した環境を接続してください。",
  "Stored secret, enter a new value to replace":
    "シークレットは保存済みです。置き換えるには新しい値を入力してください",
