  "Bitbucket sign-in method": "Bitbucket のサインイン方法",
  "Access token": "アクセストークン",
  "Atlassian account email": "Atlassian アカウントのメールアドレス",
  "API token": "API トークン",
  "Without a saved token, the server falls back to its STUDIO_BITBUCKET_* environment variables.":
    "トークンが保存されていない場合、サーバーは STUDIO_BITBUCKET_* 環境変数を使います。",
  "branch naming": "ブランチの命名",
  "branch prefix": "ブランチのプレフィックス",
  "No prefix": "プレフィックスなし",
  "The model chooses a prefix that describes the work, such as feat/add-search, fix/login-timeout, or refactor/auth.":
    "モデルが作業内容を表すプレフィックスを選びます（例: feat/add-search、fix/login-timeout、refactor/auth）。",
  "branch naming instructions": "ブランチ命名の指示",
  "Use feature/ followed by the issue ID and a short description.":
    "feature/ の後に課題 ID と短い説明を続けてください。",
  Copy: "コピー",
  "This device cannot read that machine's settings.":
    "このデバイスからは、そのマシンの設定を読み取れません。",
  "1. Install the SpecWithCode Browser extension": "1. SpecWithCode Browser 拡張機能をインストール",
  "Add to Chrome": "Chrome に追加",
  "(opens the Chrome Web Store)": "（Chrome ウェブストアを開きます）",
  "Chrome Web Store link": "Chrome ウェブストアのリンク",
  "Install it in Chrome on {machine}: copy the link and open it there, in the profile agents should use.":
    "{machine} の Chrome にインストールしてください。リンクをコピーして、エージェントが使うプロファイルで開きます。",
  "Open the link in the Chrome profile agents should use. Chrome keeps the extension up to date.":
    "エージェントが使う Chrome プロファイルでリンクを開いてください。拡張機能は Chrome が自動で更新します。",
  "2. Pair it with {machine}": "2. {machine} とペアリング",
  "This code works only in Chrome on {machine}, not in Chrome on {thisComputer}.":
    "このコードは {machine} の Chrome でのみ有効で、{thisComputer} の Chrome では使えません。",
  "Show pairing code": "ペアリングコードを表示",
  "Pairing code": "ペアリングコード",
  "pairing code": "ペアリングコード",
  "Reset code": "コードをリセット",
  "The code lets a Chrome profile act for agents on {machine}. Keep it private.":
    "このコードにより、Chrome プロファイルが {machine} のエージェントの代わりに操作できるようになります。他人に教えないでください。",
  "You are on {b}. This sets up Chrome on {b2}, a different computer; its pairing code does not work in Chrome here.":
    "現在 {b} にいます。ここでは別のコンピューター {b2} の Chrome を設定します。そのペアリングコードはこの Chrome では使えません。",
  "Set up Chrome on {thisComputer}": "{thisComputer} の Chrome を設定",
  "Every chat, project thread and Percy on {machine}, with any provider, uses the paired Chrome profile at the same time. Each works in its own tabs, in the blue SpecWithCode tab group. Threads on your other connected machines can use it too, once you allow that machine here.":
    "{machine} のすべてのチャット、プロジェクトのスレッド、Percy は、どのプロバイダーでも、ペアリング済みの Chrome プロファイルを同時に使います。それぞれ青い SpecWithCode のタブグループ内の自分のタブで作業します。ここで許可すれば、接続済みの他のマシンのスレッドも使えます。",
  "Test connection": "接続をテスト",
  Reconnect: "再接続",
  "This device can view {machine}'s Chrome but not pair or test it.":
    "このデバイスでは {machine} の Chrome を表示できますが、ペアリングやテストはできません。",
  "Reading Chrome on {machine}…": "{machine} の Chrome を読み取っています…",
  "Pair another Chrome profile": "別の Chrome プロファイルをペアリング",
  "Your other machines": "その他のマシン",
  "was declined": "拒否されました",
  "This device cannot change who may use {machine}'s Chrome.":
    "このデバイスからは、{machine} の Chrome を使えるユーザーを変更できません。",
  "Checked {value}": "確認: {value}",
  Answered: "応答あり",
  "No answer": "応答なし",
  "Use SpecWithCode Browser in Claude threads": "Claude のスレッドで SpecWithCode Browser を使う",
  "While a Chrome profile is paired with {machine}, Claude threads there start without Claude in Chrome, so agents use the profile named above instead of asking you to pick a browser. Off keeps Claude in Chrome. Applies from a thread's next message.":
    "Chrome プロファイルが {machine} とペアリングされている間、そこの Claude スレッドは Claude in Chrome なしで開始されるため、エージェントはブラウザーの選択を求めずに上記のプロファイルを使います。オフにすると Claude in Chrome を使い続けます。スレッドの次のメッセージから適用されます。",
  "A thread no longer listed": "一覧にないスレッド",
  "{span} on {machine}": "{machine} の {span}",
  "Untitled thread": "無題のスレッド",
  "Paired Chrome profiles": "ペアリング済みの Chrome プロファイル",
  "{browser} · extension {extensionVersion} · connected {value} · {value2}":
    "{browser} · 拡張機能 {extensionVersion} · 接続 {value} · {value2}",
  "Loaded by hand, so it does not update itself. Remove it in {code}, then {a} and pair it under Pair another Chrome profile, with the same name.":
    "手動で読み込まれたため、自動では更新されません。{code} で削除してから{a}、「別の Chrome プロファイルをペアリング」で同じ名前でペアリングしてください。",
  "add it from the Chrome Web Store{externalLinkIcon}{span}":
    "Chrome ウェブストアから追加{externalLinkIcon}{span}",
  "{threadLabel} · {tabs} tab · last action {value2}":
    "{threadLabel} · {tabs} タブ · 最後の操作 {value2}",
  "Recent agent actions": "最近のエージェントの操作",
  "Quit {name} to import": "インポートするには {name} を終了してください",
  "{name} is open, so its cookies can’t be read yet. Quit it, then continue.":
    "{name} が開いているため、Cookie をまだ読み取れません。終了してから続けてください。",
  "I’ve quit it": "終了しました",
  "Let SpecWithCode read {name}’s cookies": "SpecWithCode に {name} の Cookie の読み取りを許可",
  "To import cookies from {name}, SpecWithCode needs Full Disk Access. Turn it on in System Settings, then come back to finish the import — you can revoke it again once the import is done.":
    "{name} から Cookie をインポートするには、SpecWithCode にフルディスクアクセスが必要です。システム設定でオンにしてから戻り、インポートを完了してください。インポート後はまた取り消せます。",
  "Access is still required. Quit and reopen SpecWithCode if you just allowed it, then retry the import.":
    "まだアクセス権が必要です。許可したばかりなら、SpecWithCode を終了して開き直し、インポートをやり直してください。",
  "If access doesn't update after you allow it, quit and reopen SpecWithCode, then retry the import.":
    "許可してもアクセス権が更新されない場合は、SpecWithCode を終了して開き直し、インポートをやり直してください。",
