  "{providerName} on {environmentLabel}": "{environmentLabel} の {providerName}",
  "Agents publish, read dashboards and fill forms in your real Chrome, signed in as you. Pick the computer whose Chrome you are setting up: Chrome pairs only with SpecWithCode on its own computer.":
    "エージェントは、あなたとしてサインインした実際の Chrome で、投稿、ダッシュボードの閲覧、フォーム入力を行います。設定する Chrome があるコンピューターを選んでください。Chrome は同じコンピューター上の SpecWithCode とだけペアリングします。",
