  "The SpecWithCode service this app is connected to (version {serverVersion}) is older than Google account support. Update that service to use it.":
    "このアプリが接続している SpecWithCode サービス（バージョン {serverVersion}）は Google アカウントに対応する前のものです。使うにはそのサービスを更新してください。",
  "Your own OAuth client": "独自の OAuth クライアント",
  "{value}In Google Cloud Console, enable the Gmail, Google Calendar and Google Drive APIs, set up the consent screen, then create credentials of type {span} and application type {span2}. Paste its ID and secret here.":
    "{value}Google Cloud Console で Gmail、Google Calendar、Google Drive の API を有効にし、同意画面を設定してから、種類が {span}、アプリケーションの種類が {span2} の認証情報を作成します。その ID とシークレットをここに貼り付けてください。",
  "OAuth client ID": "OAuth クライアント ID",
  "Desktop app": "デスクトップ アプリ",
  "Google OAuth client ID": "Google OAuth クライアント ID",
