  "A client ID ends in .apps.googleusercontent.com.":
    "クライアント ID は .apps.googleusercontent.com で終わります。",
  "Save client": "クライアントを保存",
  "Your OAuth client {span}": "OAuth クライアント {span}",
  "Replace client": "クライアントを置き換える",
  "not connected": "未接続",
  "Label, such as Work or Personal": "ラベル（例: 仕事、個人）",
