  "Pair with a private QR code": "非公開の QR コードでペアリング",
  "Computer address · no pairing code": "コンピューターのアドレス · ペアリングコードなし",
  "Copy computer address": "コンピューターのアドレスをコピー",
  "This window cannot create pairing codes. Reopen SpecWithCode with access to this computer.":
    "このウィンドウではペアリングコードを作成できません。このコンピューターにアクセスできる状態で SpecWithCode を開き直してください。",
  "Ready to scan. The phone has not confirmed a connection yet.":
    "スキャンの準備ができました。スマートフォンはまだ接続を確認していません。",
  "This code expired. Generate a new code when your phone is ready.":
    "このコードの期限が切れました。スマートフォンの準備ができたら新しいコードを生成してください。",
  "The computer address changed. Generate a new code for this address.":
    "コンピューターのアドレスが変わりました。このアドレス用に新しいコードを生成してください。",
  "Set up Tailscale HTTPS": "Tailscale HTTPS を設定",
  "Copy pairing link": "ペアリングリンクをコピー",
  "Generate pairing code": "ペアリングコードを生成",
  "Generate new code": "新しいコードを生成",
  "This is the entire report. It contains versions, diagnostic counts, and failure categories. Conversation content, raw logs, files, credentials, paths, and identifiers are excluded.":
    "これがレポートのすべてです。バージョン、診断の件数、失敗の分類が含まれます。会話の内容、生のログ、ファイル、認証情報、パス、識別子は除外されます。",
  "Diagnostics report preview": "診断レポートのプレビュー",
  "I reviewed this report": "このレポートを確認しました",
  "I reviewed this report and want to save a copy.": "このレポートを確認し、コピーを保存します。",
  "Save report": "レポートを保存",
  "The file is saved on your device. Share it with support only if you choose.":
    "ファイルはデバイスに保存されます。サポートと共有するかどうかはあなたが決めます。",
  "Data and privacy": "データとプライバシー",
  "You control what you share.": "何を共有するかはあなたが決めます。",
  "Chat history, uploaded attachments, server settings, and diagnostic logs are stored on the environment you use. Provider logs and terminal output can contain conversation content or sensitive data.":
    "チャット履歴、アップロードした添付ファイル、サーバー設定、診断ログは、使用している環境に保存されます。プロバイダーのログやターミナルの出力には、会話の内容や機密データが含まれることがあります。",
  "Drafts, preferences, and cached interface data can also remain on the device where you use the app, including with a remote environment. Drafts can contain prompts, attachment details, and selected terminal text.":
    "下書き、設定、キャッシュされた画面データも、アプリを使うデバイスに残ることがあります（リモート環境を使う場合を含む）。下書きにはプロンプト、添付ファイルの詳細、選択したターミナルのテキストが含まれることがあります。",
  "When you start an agent turn or use a connected service, the selected provider receives the context needed for that request under its own privacy policy.":
    "エージェントのターンを開始したり接続済みのサービスを使ったりすると、選択したプロバイダーは、そのリクエストに必要なコンテキストを自社のプライバシーポリシーに基づいて受け取ります。",
  "Send crash and error reports automatically": "クラッシュとエラーのレポートを自動送信",
  "On by default. Sends the app version, OS, architecture, failure category, provider and model when relevant, a sanitized error and stack with home paths removed, and a random install id. Never sends prompts, responses, files, tokens, or account or conversation ids. Setting STUDIO_CRASH_REPORTS=false on the server also turns it off.":
    "既定でオンです。アプリのバージョン、OS、アーキテクチャ、失敗の種類、必要に応じてプロバイダーとモデル、ホームパスを除いた整形済みのエラーとスタック、ランダムなインストール ID を送信します。プロンプト、応答、ファイル、トークン、アカウントや会話の ID は送信しません。サーバーで STUDIO_CRASH_REPORTS=false を設定してもオフになります。",
  "Turned off by STUDIO_CRASH_REPORTS or team rules on this server.":
    "このサーバーでは STUDIO_CRASH_REPORTS またはチームのルールによりオフです。",
  "Update this server to change crash report settings.":
    "クラッシュレポートの設定を変更するには、このサーバーを更新してください。",
  "Product usage collection": "製品の利用状況の収集",
  "Collection is off by default. If enabled by the server operator, usage events include provider and model choices, turn results, durations, and token totals. They exclude prompts, responses, and file contents.":
    "収集は既定でオフです。サーバーの運用者が有効にした場合、利用イベントにはプロバイダーとモデルの選択、ターンの結果、所要時間、トークンの合計が含まれます。プロンプト、応答、ファイルの内容は含まれません。",
  "Local diagnostic collection helps troubleshoot problems. External trace, metric, and log export is separate from product usage collection and can be configured by the server operator.":
    "ローカルの診断収集は問題の解決に役立ちます。外部へのトレース、メトリクス、ログのエクスポートは製品の利用状況の収集とは別で、サーバーの運用者が設定できます。",
  "Connect an environment to inspect its diagnostic export settings.":
    "診断のエクスポート設定を確認するには環境を接続してください。",
  "Technical details": "技術的な詳細",
  "There is no built-in analytics destination. Enabling collection requires STUDIO_TELEMETRY_ENABLED=true and a PostHog host and key on the server. To disable it, set STUDIO_TELEMETRY_ENABLED=false and restart the server. External OpenTelemetry export is configured separately. These indicators show startup settings, not confirmed delivery.":
    "組み込みの分析の送信先はありません。収集を有効にするには、サーバーで STUDIO_TELEMETRY_ENABLED=true と PostHog のホストとキーが必要です。無効にするには STUDIO_TELEMETRY_ENABLED=false を設定してサーバーを再起動します。外部への OpenTelemetry のエクスポートは別に設定します。これらの表示は起動時の設定を示すもので、送信が確認されたことを示すものではありません。",
  "Create a report from the selected environment, review every field, then save it if you want to share it. Creating a report does not upload it.":
    "選択した環境からレポートを作成し、すべての項目を確認してから、共有したい場合は保存してください。レポートを作成してもアップロードはされません。",
