  "Choose a registered project…": "登録済みプロジェクトを選択…",
  "Opening…": "開いています…",
  "A clear desk.": "デスクはすっきりしています。",
  "Add your first project.": "最初のプロジェクトを追加しましょう。",
  "Untitled session": "無題のセッション",
  "Project unavailable": "プロジェクトを利用できません",
  "What you can do": "できること",
  "{done} of {total} done": "{done}/{total} 完了",
  "Dismiss What you can do": "「できること」を閉じる",
  "Toggle Sidebar": "サイドバーの表示を切り替え",
  "Resize Sidebar": "サイドバーのサイズを変更",
  "Drag to resize sidebar": "ドラッグしてサイドバーのサイズを変更",
  "Each paragraph or code block appears as soon as it is complete.":
    "各段落やコードブロックは完成し次第表示されます。",
  "Text appears once the agent finishes its turn.":
    "テキストはエージェントがターンを終えた時点で表示されます。",
  "Suggest a next prompt after each reply: Claude's own, or one written by the text generation model for other providers. Press Tab to use it.":
    "返信のたびに次のプロンプトを提案します。Claude 自身のもの、または他のプロバイダー向けにテキスト生成モデルが書いたものです。Tab で使用します。",
  "Suggest a next prompt only when Claude sends one with its reply. Press Tab to use it.":
    "Claude が返信と一緒に送ったときだけ次のプロンプトを提案します。Tab で使用します。",
  "Never suggest a next prompt.": "次のプロンプトを提案しません。",
  "Pauses probes for idle clients, locked hosts, or low power mode.":
    "アイドル状態のクライアント、ロック中のホスト、低電力モードでは確認を一時停止します。",
  "Allows scoped background probes while any subscribed client remains connected.":
    "購読中のクライアントが接続している間は、範囲を限定したバックグラウンド確認を許可します。",
  "Also pauses background probes when the host or client is on battery.":
    "ホストまたはクライアントがバッテリー駆動のときもバックグラウンド確認を一時停止します。",
  "Hide thinking, tool runs and in-between messages; one line per turn, opened on click":
    "思考、ツール実行、途中のメッセージを非表示にし、ターンごとに 1 行にまとめてクリックで開きます",
  "Fold finished turns and tool groups": "完了したターンとツールのグループを折りたたむ",
  "Open every turn, tool call and thought": "すべてのターン、ツール呼び出し、思考を展開する",
  "In each project, matches recent change descriptions and change request titles.":
    "各プロジェクトで、最近の変更説明と変更リクエストのタイトルに合わせます。",
  "Use Conventional Commit prefixes and keep change request text concise.":
    "Conventional Commits のプレフィックスを使い、変更リクエストの文章を簡潔にします。",
  "Use your instructions for change descriptions and change requests in every project.":
    "すべてのプロジェクトで、変更説明と変更リクエストにあなたの指示を使います。",
  "Network settings are managed where this server runs.":
    "ネットワーク設定は、このサーバーが動作している場所で管理されます。",
  "Bound to this machine. Private HTTPS and SSH tunnels can still provide remote access.":
    "このマシンに限定されています。プライベートな HTTPS や SSH トンネルなら引き続きリモートアクセスできます。",
  "Remote connections are enabled. Pairing is required for access.":
    "リモート接続が有効です。アクセスにはペアリングが必要です。",
  "Check the server launch settings for its listener address.":
    "待ち受けアドレスはサーバーの起動設定で確認してください。",
  "Automatic capture isn't available here. Choose a window instead.":
    "ここでは自動キャプチャを利用できません。代わりにウィンドウを選んでください。",
  "Capture a window and attach it to your current draft.":
    "ウィンドウをキャプチャして現在の下書きに添付します。",
  "This desktop only provides a screenshot.":
    "このデスクトップではスクリーンショットのみ取得できます。",
  "Update the desktop app to use snapshots.":
    "スナップショットを使うにはデスクトップアプリを更新してください。",
  "Unknown — this environment does not report its usage collection settings.":
    "不明 — この環境は使用状況の収集設定を報告していません。",
  "On — usage events are enabled for a configured destination.":
    "オン — 設定済みの送信先に対して使用状況イベントが有効です。",
  "Unknown — collection configuration is incomplete.": "不明 — 収集の設定が不完全です。",
  "Off — a destination is configured, but collection is disabled.":
    "オフ — 送信先は設定されていますが、収集は無効です。",
  "Off — no analytics destination is configured.": "オフ — 分析の送信先は設定されていません。",
  "Account not reported": "アカウントは報告されていません",
  "Apps allowed on this machine": "このマシンで許可されたアプリ",
  "No apps allowed on this machine yet. When an agent asks to use an app, choose Always on this machine to stop it asking again.":
    "このマシンで許可されたアプリはまだありません。エージェントがアプリの使用を求めたときに「このマシンで常に許可」を選ぶと、再度確認されなくなります。",
  "Devices allowed on this machine": "このマシンで許可されたデバイス",
  "No devices allowed on this machine yet. When an agent asks to use a device, choose Always on this machine to stop it asking again.":
    "このマシンで許可されたデバイスはまだありません。エージェントがデバイスの使用を求めたときに「このマシンで常に許可」を選ぶと、再度確認されなくなります。",
  "Enable this environment to open simulators and emulators, whether they run here or on a remote device host.":
    "この環境で、ここまたはリモートのデバイスホストで動くシミュレーターとエミュレーターを開けるようにします。",
  "Allow new agent sessions in this environment to start and control local and remote devices, with required tools set up automatically.":
    "この環境の新しいエージェントセッションが、ローカルおよびリモートのデバイスを起動・操作できるようにします。必要なツールは自動で設定されます。",
  "Each AI tool keeps its own MCP list, so a server enabled in Claude Code is not available in Codex until it is added there too.":
    "AI ツールごとに MCP リストは別なので、Claude Code で有効にしたサーバーも、Codex に追加するまでは Codex で使えません。",
  "Claude Code loads these only when it runs in that folder. Other folders, projects and providers do not get them. They are stored in your ~/.claude.json.":
    "Claude Code はそのフォルダーで実行するときだけこれらを読み込みます。他のフォルダー、プロジェクト、プロバイダーには渡りません。これらは ~/.claude.json に保存されています。",
  "Codex user config.toml": "Codex のユーザー config.toml",
