    "このデバイスはオフラインです。保存済みのチャットは古い可能性があります。作業を始める前に再接続してください。",
  "Try a shorter name, or switch between Open and Done.":
    "短い名前を試すか、「未完了」と「完了」を切り替えてください。",
  move: "移動",
  open: "開く",
  "this machine": "このマシン",
